class Solution:
    def minCameraCover(self, root: Optional[TreeNode]) -> int:
        if root is None:
            return 0
        nodes = []
        parent = {}

        def collect(node, par):
            if node is None:
                return
            nodes.append(node)
            parent[node] = par
            collect(node.left, node)
            collect(node.right, node)

        collect(root, None)
        n = len(nodes)
        best = n
        # 枚举每个节点「放 / 不放」摄像头，共 2^n 种方案
        for mask in range(1 << n):
            cnt = 0
            covered = set()
            for i in range(n):
                if mask >> i & 1:
                    cnt += 1
                    node = nodes[i]
                    covered.add(id(node))
                    if parent[node] is not None:
                        covered.add(id(parent[node]))
                    if node.left:
                        covered.add(id(node.left))
                    if node.right:
                        covered.add(id(node.right))
            if cnt >= best:
                continue
            if all(id(node) in covered for node in nodes):
                best = cnt
        return best

