class Solution:
    def numTrees(self, n: int) -> int:
        # dp[i]：i 个连续节点能构成的互不相同的 BST 个数
        dp = [0] * (n + 1)
        dp[0] = 1  # 空树算 1 种方案，也是递推的乘法单位元
        for i in range(1, n + 1):
            for j in range(1, i + 1):
                # 以 j 为根：左子树 j-1 个节点，右子树 i-j 个节点
                dp[i] += dp[j - 1] * dp[i - j]
        return dp[n]

