class Solution:
    def maxProfit(self, prices: List[int]) -> int:
        # dp[k][0]：最多完成 k 次交易且当前不持股的最大利润
        # dp[k][1]：最多完成 k 次交易且当前持股的最大利润
        dp = [[0, -float("inf")] for _ in range(3)]
        for p in prices:
            for k in range(1, 3):
                dp[k][1] = max(dp[k][1], dp[k - 1][0] - p)  # 第 k 次买入
                dp[k][0] = max(dp[k][0], dp[k][1] + p)  # 第 k 次卖出
        return dp[2][0]

